head.script:
scwin.onpageload = function() {
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
};
scwin.onpageunload = function() {};
scwin.ibx_openPopup_onclick1 = function(e) {
    var uri = "window_WEFF-500_(WSQ-3873)_sub.xml";
    var opts = {
        "id": "wframePopup",
        "type": "wframePopup",
        "width": "700px",
        "height": "250px",
        "top": 150,
        "left": 150,
        "popupName": "wframePopup",
        "modal": false,
        "title": "wframe popup",
        "foldOnMinimized": true,
        "windowDragMove": true
    };
    scwin.$w.openPopup(uri, opts);
};
