        "type": "iframePopup",
        "width": "700px",
        "height": "250px",
        "top": 150,
        "left": 150,
        "popupName": "iframePopup",
        "modal": false,
        "title": "iframe popup",
        "foldOnMinimized": true,
        "windowDragMove": true
    };
    scwin.$w.openPopup(uri, opts);
